INSERT INTO purpose VALUES('surface-grammar','automaton::MoldSet','struct','Views one tile set''s molds as its words, so a candidate menu is admitted by one union of words and a bit test per candidate.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','automaton::MoldWord','struct','Holds sixty-four consecutive molds'' membership in one tile set, so a candidate menu is admitted by one union of words.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','automaton::MoldWordIndex','struct','Names the word of a tile set that covers a mold, so a mold''s membership is read as a bit test.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','automaton::Observation','struct','Names the class of molds a parser reads alike once pushed, so a parser that weighs many molds over one slope pushes one per class.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','automaton::TileKind','enum','Names what a pushed tile is to the slope, so a parser weighs a candidate by its kind.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','automaton::TileSet','enum','Names a set of molds a parser admits by kind and sort, so a candidate menu is filtered by one bitset.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','automaton::TileTableBytes','struct','Names how many bytes a grammar''s tile tables hold, so a build reports the memory a given grammar''s tables take.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','check::validate_assumption_3','function','Checks a rule set against Assumption 3, so a grammar whose sorts can each begin and end the other''s forms is refused.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','check::validate_operator_form','function','Checks one rule''s form against Operator Form, so a form that puts two holes side by side on any path is refused.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','check::validate_unique_tiles','function','Checks a rule set against Unique Tiles, so a label and a context that name two molds are refused.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','highlight::HighlightError','enum','Names every refusal of the highlighter, so a tree molded under another grammar or a tile past the table is refused.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','highlight::RoleTable','struct','Holds one highlight role per mold of a grammar, so a molded tree''s tiles are read through it into spans.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::Adaptation','struct','Holds an adaptation record, where a rule''s shape departs from the surface form it realises and why, so the parity inventory documents the departure.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::AdaptationReason','struct','Names why a rule''s shape departs from the surface form it realises, so an adaptation record states its cause.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::CandidateCount','struct','Names how many molds one tile label can take, so a parser''s candidate menu is sized.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::LabelText','struct','Names a label as a token spells it, declared or not, so a parser resolves it to the declared tile label.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::LeftOperand','enum','Names what a rule admits as its left operand, any whole operand or a name, so the melder refuses a qualified path over a whole form.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::MoldCount','struct','Names how many molds a grammar declares, so a build reports the table''s size.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::Pbg','struct','Holds the checked precedence-bounded grammar, which exists only once its three build-time gates have passed, so a parser and a highlighter read the molds and the relations it holds.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::PbgError','enum','Names every refusal of grammar construction and lookup, so a build or a lookup reports the fault.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::PrecName','struct','Names one precedence group, so a rule and a precedence DAG are keyed by it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::PrecPresence','struct','Names whether a precedence table names a group, so a lookup reports its absence.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::PrecTable','struct','Holds a built precedence DAG with its groups'' names, so a rule names the group it stands at.',NULL,'fits','sound',NULL);
