INSERT INTO purpose VALUES('surface-grammar','model::Regex','struct','Holds a regular expression over grammar symbols, stored flat in pre-order, so a rule''s form is walked without a pointer to its own type.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::RegexShape','enum','Names the root of a regex subtree with its children as views, so a form is read one level deep.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::RegexView','struct','Holds a borrowed subtree of a regex, so a form is walked by offset.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::Removal','enum','Names whether an adaptation record keeps a shape of the surface, or an old spelling that the grammar still parses with its replacement and the issue that removes it, so the syntax ledger marks each old spelling.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::RemovalIssue','struct','Names the tracker issue that removes an old spelling, so check:ledger reads its state.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::Replacement','struct','Names the spelling that stays in the place of an old one, so the syntax ledger row points a reader at it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::Rule','struct','Holds one grammar rule, a named form of one sort at one precedence, so a grammar is built from its rules.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::RuleName','struct','Names one grammar rule, so a rule is named in a refusal or a provenance.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::Sort','enum','Names a grammar sort, the closed set of things a hole can stand for, so a rule and a mold are keyed by it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::SortName','struct','Names the display name of one grammar sort, so a refusal names it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::SurfaceForm','struct','Names the surface form an adaptation record documents, so the parity inventory names what a rule realises.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::Sym','enum','Names one symbol of a regular grammar expression, so a form is built from its symbols.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::Tile','struct','Names a terminal tile, declared by label alone, so a mold, its context, precedence and sort, is assigned per occurrence when the grammar is built.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','model::TileLabel','struct','Names the label of one tile, the token class a lexer emits for it, so a mold and a highlight role are keyed by it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','mold::HoleFollows','struct','Names whether a hole can follow a mold within its form, so a parser admits an operand after it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','mold::LabelFollowsForm','struct','Names whether a token can stand right after a whole form of a sort, so a parser admits a continuation.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','mold::LabelId','struct','Names a declared label by its number in the grammar''s label table, so a parser resolves a token''s spelling once and reads its menus by number.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','mold::MoldDef','struct','Holds one mold, a tile occurrence''s zipper into the grammar, with its precedence bounds and zipper steps precomputed, so a tree''s mold id indexes it.',NULL,'fits','sound',NULL);
