INSERT INTO purpose VALUES('surface-grammar','mold::MoldHasRequiredTail','struct','Names whether a mold can end its form only once a trailing hole is filled, so a parser and the tile automaton read its kind.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','mold::MoldHasSuccessor','struct','Names whether a mold has a same-form successor, so a parser and the tile automaton read its kind.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','mold::MoldInSet','struct','Names whether a mold belongs to a tile set, so a parser admits it by its kind and sort.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','mold::MoldIsFormFirst','struct','Names whether a mold can open a form, so a parser and the tile automaton read its kind.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','mold::MoldIsFormLast','struct','Names whether a mold can complete its form with no hole still required, so a parser and the tile automaton read its kind.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','mold::MoldsAdjacent','struct','Names whether two molds are same-form adjacent, left then right, so a parser reads the operator-precedence relation.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','mold::RCtxId','struct','Names an interned regex-zipper context, a position in one rule''s form, so a mold''s zipper into the grammar is keyed by it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','mold::RCtxStep','struct','Names one precomputed zipper step, the symbol crossed, so a context''s steps out are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','mold::StepSym','enum','Names one symbol the zipper crosses stepping out of a context, so a context''s steps are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','parity::NamedKind','struct','Names a named kind''s text, so the inventory classifies it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','parity::NamedKindEntry','struct','Holds one row of the named-kind inventory, so a named kind''s realization is checked.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','parity::NamedKindRealization','enum','Names how a named kind is realised, so the inventory is checked against an editor-facing grammar.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','parity::named_kind_parity','function','Holds the named-kind inventory, classifying every named node kind of the surface''s tree-sitter grammar, so coverage of the named kinds is checked.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','parity::named_kind_realization','function','Classifies how a named kind is realised, so the inventory records whether it is the file root, layout or structural forms.',NULL,'fits','sound',NULL);
