INSERT INTO purpose VALUES('surface-grammar','surface::TREE_SITTER_NAMED_KINDS','constant','Names the named node kinds of the surface''s tree-sitter grammar, so the parity inventory is checked against them.',NULL,'fits','sound',NULL);
