INSERT INTO purpose VALUES('surface-grammar','surface::built_in_prec_table','function','Builds the built-in precedence table, so a rule names the group it stands at.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','walk::Comparison','enum','Names one operator-precedence comparison, so a comparison table row is read.',NULL,'fits','sound',NULL);
