INSERT INTO purpose VALUES('surface-grammar','walk::GrammarNonterminal','struct','Names a grammar nonterminal, a form group, so the walk machine''s walks are carried over it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','walk::GrammarTile','struct','Names a walk stance, one mold, so the walk machine''s walks are carried over it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','walk::GrammarWalkSym','struct','Names the grammar''s symbol vocabulary for the walk machine, so a walk index is built over the molds.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-grammar','walk::MAX_WALK_CHAIN_LEN','constant','Names the longest alternating chain the walk index materialises, so an over-long walk is a typed refusal.',NULL,'fits','sound',NULL);
